var rot = function (q) {
  var h = 0;
  for (var i = 0; i < q.id.length; i++) h = (h * 31 + q.id.charCodeAt(i)) % 997;
  var n = q.o.length, r = h % n;
  if (r === 0) return q;
  var o = q.o.map(function (_, i) { return q.o[(i + r) % n]; });
  var a = q.a.map(function (x) { return (x - r + n) % n; }).sort(function (x, y) { return x - y; });
  var c = {}; for (var k in q) c[k] = q[k]; c.o = o; c.a = a; return c;
};
